steps.code:
# Move each file from backslash path to forward slash path
for src in files_root:
    # Replace backslash with forward slash to get correct destination
    dst = src.replace('\\', '/')
    if src != dst:
        result = apis.file_system.move_file(
            access_token=access_token,
            source_file_path=src,
            destination_file_path=dst
        )
        print(f"Moved {src} -> {dst}: {result}")
    else:
        print(f"No change needed for {src}")

