steps.code:
# Check if current song is liked, if not go previous until we find a liked song
liked_ids = {song['song_id'] for song in liked_songs}
current = apis.spotify.show_current_song(access_token=access_token)
print("Current song:", current)
if current['song_id'] in liked_ids:
    print("Already liked, no need to go previous.")
else:
    # Go previous until we find a liked song
    for _ in range(len(queue)):
        apis.spotify.previous_song(access_token=access_token)
        current = apis.spotify.show_current_song(access_token=access_token)
        print("After previous, current song:", current)
        if current['song_id'] in liked_ids:
            break
    else:
        print("No liked song found in queue after full cycle.")

