# Get details for each playlist to see songs
playlist_details = {}
for p in playlists:
    pid = p['playlist_id']
    detail = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_login['access_token'])
    playlist_details[pid] = detail
    print(f"Playlist {pid} ({detail['title']}): {len(detail.get('songs', []))} songs")
    for song in detail.get('songs', []):
        print(f"  Song ID {song['id']}: {song['title']}")

# Collect all matching song IDs and which playlists they appear in
matching_song_ids = set()
playlist_song_matches = {}  # playlist_id -> list of song_ids to remove

for pid, detail in playlist_details.items():
    matches = []
    for song in detail.get('songs', []):
        if song['title'] in song_titles:
            matches.append(song['id'])
            matching_song_ids.add(song['id'])
    if matches:
        playlist_song_matches[pid] = matches

print("Matching song IDs:", matching_song_ids)
print("Playlist matches:")
for pid, ids in playlist_song_matches.items():
    print(f"  Playlist {pid}: {ids}")

