# Verify the final state of all playlists
all_playlists_after = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(
        access_token=login_result["access_token"],
        page_index=page_index,
        page_limit=20
    )
    all_playlists_after.extend(page)
    if len(page) < 20:
        break
    page_index += 1

archived_song_ids = [song_id for song_id, _, _ in song_ids_to_archive]

# Check each playlist
for pl in all_playlists_after:
    pl_id = pl['playlist_id']
    pl_songs = pl.get('song_ids', [])
    # Check if any archived song remains
    remaining = [sid for sid in pl_songs if sid in archived_song_ids]
    if pl_id == 654:
        print(f"Old Songs playlist {pl_id}: {pl['title']} - songs: {pl_songs}")
        missing = [sid for sid in archived_song_ids if sid not in pl_songs]
        if missing:
            print(f"  MISSING archived songs: {missing}")
        else:
            print("  All archived songs present.")
    else:
        if remaining:
            print(f"Playlist {pl_id} ({pl['title']}) still contains archived songs: {remaining}")
        else:
            print(f"Playlist {pl_id} ({pl['title']}) clean.")

# Verify removals and confirm "Old Songs" playlist has all archived songs
# Re-fetch all playlists to check current state
all_playlists_after = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    all_playlists_after.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Check each playlist (except 654) has no archived songs
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
clean = True
for p in all_playlists_after:
    if p["playlist_id"] != 654:
        for sid in p["song_ids"]:
            if sid in archived_song_ids:
                print(f"ERROR: song {sid} still in playlist {p['playlist_id']}")
                clean = False
    else:
        # Verify Old Songs has all 18
        if len(p["song_ids"]) != len(song_ids_to_archive):
            print(f"Old Songs has {len(p['song_ids'])} songs, expected {len(song_ids_to_archive)}")
            clean = False
        else:
            missing = archived_song_ids - set(p["song_ids"])
            if missing:
                print(f"Missing from Old Songs: {missing}")
                clean = False

if clean:
    print("All removals verified and Old Songs contains all archived songs.")
else:
    print("Verification failed.")

