steps.code:
# Let's search for each remaining song and collect their song_ids.
# We already have the first song's search result, but let's do all in a loop for consistency.
song_ids = {}
for song in songs_to_archive:
    title = song['title']
    artists = song['artists']
    # Search by title
    results = apis.spotify.search_songs(query=title, access_token=spotify_login['access_token'])
    # Find exact match: title matches and at least one artist matches
    found = None
    for r in results:
        if r['title'].lower() == title.lower():
            # Check if any artist in r['artists'] matches any of the target artists
            r_artist_names = [a['name'] for a in r['artists']]
            if any(any(art.lower() == rn.lower() for rn in r_artist_names) for art in artists):
                found = r
                break
    if found:
        song_ids[title] = found['song_id']
        print(f"Found: {title} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {title}")

print("song_ids:", song_ids)

