# Re-fetch release dates for the 10 songs from history
# We'll store them in a dictionary mapping song title to release_date
release_dates = {}

# Tangled Lies
res = apis.spotify.search_songs(query='TangledLiesAvaMorgan', page_limit=5)
# Find the exact song
for song in res:
    if song['title'] == 'Tangled Lies':
        release_dates['Tangled Lies'] = song['release_date']
        break

# Lost in the Wilderness of Love
res = apis.spotify.search_songs(query='LostintheWildernessofLoveLilyMoonZoeyJames', page_limit=5)
for song in res:
    if song['title'] == 'Lost in the Wilderness of Love':
        release_dates['Lost in the Wilderness of Love'] = song['release_date']
        break

