# The Forgotten Pages of Time
res = apis.spotify.search_songs(query='TheForgottenPagesofTimeLunaStarlight', page_limit=5)
for song in res:
    if song['title'] == 'The Forgotten Pages of Time':
        release_dates['The Forgotten Pages of Time'] = song['release_date']
        break

# Summer's End
res = apis.spotify.search_songs(query="Summer'sEndEthanWallace", page_limit=5)
for song in res:
    if song['title'] == "Summer's End":
        release_dates["Summer's End"] = song['release_date']
        break

# A Tale of Unspoken Longing
res = apis.spotify.search_songs(query='ATaleofUnspokenLongingEmilyRivers', page_limit=5)
for song in res:
    if song['title'] == 'A Tale of Unspoken Longing':
        release_dates['A Tale of Unspoken Longing'] = song['release_date']
        break

# Cracks in the Facade of Love
res = apis.spotify.search_songs(query='CracksintheFacadeofLoveVelvetEcho', page_limit=5)
for song in res:
    if song['title'] == 'Cracks in the Facade of Love':
