# Remove all liked songs from the queue one by one, re-fetching queue each time
access_token = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJzcG90aWZ5K2NoZXdlYmVyQGdtYWlsLmNvbSIsImV4cCI6MTY4NDQxMjA5OH0.IVDEsv7W5sn2Tuim1RDI_gCZ2HGg41ltcLtvtdVDknY'
liked_ids = {19, 103, 109, 133, 135, 167, 204, 206, 229, 242, 301}

while True:
    queue = apis.spotify.show_song_queue(access_token=access_token)
    # find first position with liked song
    pos_to_remove = None
    for song in queue:
        if song['song_id'] in liked_ids:
            pos_to_remove = song['position']
            break
    if pos_to_remove is None:
        break
    print(f"Removing song at position {pos_to_remove}")
    print(apis.spotify.remove_song_from_queue(position=pos_to_remove, access_token=access_token))

print("All liked songs removed from queue")

