# Verify the queue no longer contains any liked songs
queue = apis.spotify.show_song_queue(access_token=access_token)
liked_ids = {19, 103, 109, 133, 135, 167, 204, 206, 229, 242, 301}
remaining_liked = [song for song in queue if song['song_id'] in liked_ids]
print(f"Queue length after removal: {len(queue)}")
print(f"Liked songs still in queue: {len(remaining_liked)}")
if remaining_liked:
    print("Remaining liked songs:", [s['song_id'] for s in remaining_liked])
else:
    print("All liked songs removed successfully.")

